using System.Text.Json;
namespace AnkaStudio;

public sealed class WorkflowTimeline : Control
{
    public VideoScript Script {get;}
    public int Selected {get;private set;}
    public event Action<int>? SelectedChanged;
    public event Action? BeforeEdit;
    public event Action? Edited;
    public event Action<double>? Seek;
    int boundary=-1;double originalLeft,originalRight,originX;bool changed;
    public WorkflowTimeline(VideoScript script){Script=script;DoubleBuffered=true;Width=1100;Height=100;BackColor=Theme.Panel;Cursor=Cursors.Hand;}
    public double Total=>Math.Max(.1,Script.Scenes.Sum(s=>Math.Max(.1,s.Duration)));
    double X(double t)=>12+t/Total*Math.Max(1,Width-24);
    public static void ResizeBoundary(VideoScript script,int index,double change)
    {
        if(index<0||index>=script.Scenes.Count-1)throw new InvalidOperationException("Bölüm sınırı bulunamadı.");var left=script.Scenes[index];var right=script.Scenes[index+1];double amount=Math.Clamp(change,.1-left.Duration,right.Duration-.1);left.Duration+=amount;right.Duration-=amount;
    }
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);double t=0;using var font=Theme.Font(9);using var text=new SolidBrush(Theme.Text);using var line=new Pen(Theme.Text,2);for(int i=0;i<Script.Scenes.Count;i++){var scene=Script.Scenes[i];float left=(float)X(t),right=(float)X(t+Math.Max(.1,scene.Duration));using var fill=new SolidBrush(i==Selected?Theme.AccentSurface:Theme.Elevated);e.Graphics.FillRectangle(fill,left,28,Math.Max(1,right-left-2),42);e.Graphics.DrawString((i+1)+" • "+scene.Duration.ToString("0.0")+" sn",font,text,new RectangleF(left+4,31,Math.Max(1,right-left-6),36));if(i<Script.Scenes.Count-1)e.Graphics.DrawLine(line,right,24,right,75);e.Graphics.DrawString(TimeSpan.FromSeconds(t).ToString(@"mm\:ss"),font,text,left,5);t+=scene.Duration;}e.Graphics.DrawString("Sınırları sürükle • toplam "+Total.ToString("0.0")+" sn",font,text,12,78);}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left)return;double t=0;boundary=-1;for(int i=0;i<Script.Scenes.Count;i++){t+=Script.Scenes[i].Duration;if(i<Script.Scenes.Count-1&&Math.Abs(e.X-X(t))<9){boundary=i;originalLeft=Script.Scenes[i].Duration;originalRight=Script.Scenes[i+1].Duration;originX=e.X;changed=false;BeforeEdit?.Invoke();Capture=true;return;}if(e.X<=X(t)){Selected=i;SelectedChanged?.Invoke(i);Seek?.Invoke(Math.Max(0,t-Script.Scenes[i].Duration));Invalidate();return;}}}
    protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(boundary<0)return;Script.Scenes[boundary].Duration=originalLeft;Script.Scenes[boundary+1].Duration=originalRight;ResizeBoundary(Script,boundary,(e.X-originX)/(Width-24)*Total);changed=true;Invalidate();}
    protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(boundary<0)return;boundary=-1;Capture=false;if(changed)Edited?.Invoke();}
}

public sealed class WorkflowPlayer : AxHost
{
    public WorkflowPlayer():base("6BF52A52-394A-11D3-B153-00C04F79FAA6"){Height=260;}
    public void Open(string path){dynamic player=GetOcx()!;player.settings.autoStart=false;player.URL=path;player.uiMode="full";}
    public void Seek(double seconds){dynamic player=GetOcx()!;player.controls.currentPosition=seconds;}
    protected override void Dispose(bool disposing){if(disposing&&IsHandleCreated){try{dynamic player=GetOcx()!;player.controls.stop();player.close();}catch{}}base.Dispose(disposing);}
}

